// Clean-room TSVC s235 profile; see package rights note.
fn put64(out:[*]u8,p:usize,v:i64)void{const bits=@as(u64,@bitCast(v));for(0..8)|k|out[p+k]=@truncate(bits>>(8*k));}
pub export fn tsvc_s235_fused_vector_matrix_recurrence(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<15 or length>153)return -1;const v=input.?[0..length];const nr=v[0];if(nr<2 or nr>8)return -1;const n:usize=@intCast(nr);const nn=n*n;if(length!=1+3*n+2*nn)return -1;var a=[_]i64{0}**8;var b=[_]i64{0}**8;var c=[_]i64{0}**8;var aa=[_]i64{0}**64;var bb=[_]i64{0}**64;var p:usize=1;for(0..n)|i|{const x=v[p];p+=1;if(x< -1 or x>1)return -1;a[i]=x;}for(0..n)|i|{const x=v[p];p+=1;if(x< -1 or x>1)return -1;b[i]=x;}for(0..n)|i|{const x=v[p];p+=1;if(x< -1 or x>1)return -1;c[i]=x;}for(0..nn)|i|{const x=v[p];p+=1;if(x< -1 or x>1)return -1;aa[i]=x;}for(0..nn)|i|{const x=v[p];p+=1;if(x< -1 or x>1)return -1;bb[i]=x;}if(output==null or capacity<8*(n+nn))return -2;for(0..n)|col|{a[col]+=b[col]*c[col];for(1..n)|row|{const k=row*n+col;aa[k]=aa[k-n]+bb[k]*a[col];}}for(0..n)|i|put64(output.?,8*i,a[i]);for(0..nn)|i|put64(output.?,8*(n+i),aa[i]);return @intCast(n+nn);}
